NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'Psalms'

CHAPTERS = {
    1: {
        1: "Aheya kahāpan ma a'a sasuku mbal ameya' gara' min a'a jahulaka', sasuku isab mbal pasehe' ma a'a pangandusa. Mbal iya palamud ma saga a'a ya angandali'it Tuhan,",
        2: "saguwā' kahōpan iya ma sara' ya panoho'anna ma manusiya'. Ya he' kinannal e'na llaw-sangom.",
        3: "A'a inān sali' sapantun kayu tinanom ma bihing sapa', ya amuwan buwa' ma musimna du. Minsan painay mbal pak'llos dahunna. Ai-ai hinangna, ahāp sadja tungbasna.",
        4: "Malaingkan saga a'a jahulaka' mbal buwattē'. Sapantun sigām hampa' pai ya tabowa paleyang e' baliyu.",
        5: "Ya he' sababna angkan saga a'a jahulaka' mbal makara'awa bang ta'abut nihukum, mbal isab pinalamud ma sasuku abontol atayna tudju ni Tuhan.",
        6: "Saga a'a abontol niayura na pa'in e' PANGHŪ' -Yawe, sagō' saga a'a jahulaka' ala'at sadja kat'kkahan sigām.",
    },
    2: {
        1: "Angay angkan magbantu saga kabangsa-bangsahan, angay sigām magisun ma halam aniya' pūsna?",
        2: "Magsakap di-sigām saga kasultanan, magsakaum saga pagnakura'an bo' angatu ma PANGHŪ' -Yawe, maka ma Al-Masi ya tapene'na.",
        3: "Maghimumungan saga a'a inān, yuk-i, “Gom kitam papuwas min komkoman sigām, gom b'kkattam saga kili-kili ya pangengkot sigām.”",
        4: "Saguwā' pagtittowahan sigām he' Tuhan, ya aningkō' ma sulga' magkabaya'an ma kamemon. Pinagtunggīngan sigām e' Panghū'.",
        5: "Pinabukagan saga a'a inān kabowa pangastolna, pinakitāw sigām ma sabab landu' akagit atayna.",
        6: "Yuk Tuhan ma sigām, “O'o, sultan bay tapatingkō'ku, ina'an ma Būd Siyun, ya būd kamulliyahanku.”",
        7: "Ya panambung sultan e', “Pasaplagku lapal ya pangallam aku he' PANGHŪ'.” Yukna ma aku, “Ka'a ilu tahinang anakku na. Aku ya Mma'nu tinagna'an min llaw itu.",
        8: "Bang aku ya pangamu'annu, pamusaka'ku ma ka'a kamemon bangsa, pamasuku'ku ma ka'a sakalibutan dunya.",
        9: "Ka'a ya amarinta ma kabangsa-bangsahan, ati apaslod pamarintanu sapantun tungkud basi'. Alopot sigām kamemon sali' dalil paliyuk.”",
        10: "Angkan yukku ma ka'am saga sultan, “Pata'u kam. Pahalli' kam, sasuku magbabaya' ma babaw dunya.",
        11: "Magpatireyo' kam ma PANGHŪ', pagkoyaginbi iya hinabubi magpamidpid.",
        12: "Pasiyum kam ma Anakna, ya aniya' kakagit atayna, ati taggaha' kam t'kkahan mulka'na. Sabab pasulapput astolna saru'un-du'un, malaingkan aheya kahāpan ma sasuku makabāk patapukan ma iya.”",
    },
    3: {
        1: "O Yawe, aheka saga a'a amantahan aku! Kapilahan aku e' saga a'a magpanagga' aku.",
        2: "Aheka isab saga a'a anunggīngan aku, yuk-i, “Mbal iya pinuwas e' Tuhan min kamulahan.”",
        3: "Saguwā' ka'a ya tampanku, O PANGHŪ'. Ka'a ya amuwanan aku kasahaya'an. Ka'a ya amahogot kamahaldika'anku.",
        4: "Bang aku parahing ni PANGHŪ' -Yawe, sinambungan aku e'na min būdna mulliya.",
        5: "Ahāp e'ku atuli, asannang isab kabati'ku, sabab binogbogan aku e' PANGHŪ'.",
        6: "Mbal aku tināw ma saga bantaku ibu-ibuhan, ya angalibutan aku ma paruruwambila'.",
        7: "Ya PANGHŪ', pasa'ut ka, lappasun aku min ka'aniban. Suntukun palbantahanku ma baihu' sigām, paglopotun empon sigām.",
        8: "Si Yawe ya angaliyusan aku min kamulahan. Bang pa'in buwanannu kahāpan saga a'a suku'nu.",
    },
    8: {
        1: "O Yawe, ka'a pagpanghū'an kami, kaheya du pa'in mahaltabatnu ma kaluha'an dunya! Alanga sahayanu min kapitu' lapis langit.",
        2: "Min kahandaknu saga kamanahutan amudji ōnnu, saga anak duru'an lagi' ananglitan ka'a. Angkan mbal maka'atu saga palbantahan, mbal makatukas saga magbabalos.",
        3: "Ya PANGHŪ', bang aku pahangad ni langit bo' angira-ngira kahinangan tangannu, bang nda'ku bulan maka saga bitu'un ya bay pat'nna'nu ma b'ttong langit,",
        4: "tabowa aku atilaw pasal kami manusiya'. Ai kapūsan kami angkan kami pagka'inagonannu? Angay kannalnu bangsa manusiya' ya mbal anatas itu?",
        5: "Pat'nna'nu kami areyo' dangkuri' min saga bangsa mala'ikat ya porol ma sulga'. Buwanannu kami kasanglitan maka kabantugan.",
        6: "Buwanannu kami kapatut magbaya' ma kamemon ai-ai bay paniya'nu, bo' kami makapagnakura' ma kamemon papanjarihan,",
        7: "saga sapi' maka saga bili-bili, hayop ni'ipat, maka saga sattuwa talun.",
        8: 'Makapagagi kami ma saga manuk-manuk, maka ma kaginisan daing tahik maka sattuwa dilaut.',
        9: "O Yawe, ya pagpanghū'an kami, kaheya du pa'in mahaltabatnu ma kaluha'an dunya!",
    },
    13: {
        1: "O Yawe, sumiyan aku patandung pabalik ni ataynu? Sumiyan ka pabaihu' ni aku pabīng?",
        2: "Sumiyan bahā' pahondong kalengog pikilanku itu, sabab llaw-sangom pasangdan na pa'in kasusahanku. Sumiyan pahali saga bantaku anganda'ug min aku?",
        3: "O Yawe, Tuhanku, palingi' gi' ka anambungan aku. Pasawahun pang'nda'ku, da'a aku pasagarin amatay.",
        4: "Sabab bang aku mbal dūlannu, tantu aku niudju' e' kuntaraku, yuk-i, “Nē! Tara'ug na ka!” Ati magkalasigan saga banta ma sabab kaiya'anku.",
        5: "Saguwā' angandol sadja aku ma kasi-lasanu tuman, maka magkōg-koyag ma sabab kapanglappasnu.",
        6: "O PANGHŪ', magkalang aku ni ka'a, sabab kahāpnu ma aku mbal tapula'-pula'.",
    },
    16: {
        1: "Ya Tuhan, hampanin aku, sabab ka'a ya patapukanku.",
        2: "Yukku ni si Yawe, “Ka'a ya Panghū'ku, Halam aniya' palsuku'anku ahāp saddī min ka'a.”",
        3: "Babantugun saga a'a ma lahat itu, ya atotog ameya' ma kabaya'an Tuhan. Landu' aku kasulutan ma sigām.",
        4: "Malaingkan bang a'a ameya' ma tuhan-tuhan saddī, pak'nnop na pa'in kasusahan sigām. Mbal aku palamud ma a'a inān anukbal laha', mbal minsan sibahatku ōn saga pagtuhanan sigām.",
        5: "Ka'a PANGHŪ', sapantun pusaka'ku, Ka'a ya palsuku'anku, ahāp kasōngan ya pangangganta'nu ma aku.",
        6: "Kabuwanan aku tana' ma lahat kasalamatan, landu' ahāp ya pamusaka'nu aku.",
        7: "Sanglitanku si Yawe ya angahūgan aku gara'. Minsan ma waktu sangom, kapandu'an aku luwas min pandu' ya ma deyom pangatayanku.",
        8: "Si Yawe ya pataptap ma pangatayanku. Itiya' iya ma bihingku, angkan aku mbal tabowa pajudjal.",
        9: 'Magkōg-koyag aku sampay min deyom atay, asalamat pamarananku,',
        10: "sabab mbal aku siya-siyanu ma deyom ahirat. Mbal aku pasagarannu angahalu' ma deyom paliyangan.",
        11: "Tantu aku tuli'annu lān ya amowa ni kallum. Sinōd aku kōg-koyag ma sabab kamaitunu ma aku, kahōpan aku e' kalasigan ya anatas ni kasaumulan bang ta'abutku na haddaratnu.",
    },
    19: {
        1: "Atanyag sanglit-sahaya Tuhan ma sabab paltanda'an ya ta'nda'ta ma b'ttong langit. Abantug kapandayan Tuhan ma sabab saga pandoga ma tonga'an ayan.",
        2: "Kahaba'-kahaba' llaw binuwanan kitam lapal, kahaba'-kahaba' sangom binuwanan kitam panghati.",
        3: "In bitu'un maka llaw itu ta'nda' asal ma sabarang lahat, pa'abut lapal sigām ni kalibutan dunya.",
        4: "Pasaplag pandu' sigām ni kamemon bangsa, Pasampay bissala sigām ni mpat pidju alam. In mata llaw sali' sapantun l'lla pangantin bay nihinangan luma' e' Tuhan ma langit, tampal ni sobangan. Ati paluwas iya minnē' buwat a'a bastigan ya kinōgan magdagan ma paglomba'an.",
        5: "Pasaplag pandu' sigām ni kamemon bangsa, Pasampay bissala sigām ni mpat pidju alam. In mata llaw sali' sapantun l'lla pangantin bay nihinangan luma' e' Tuhan ma langit, tampal ni sobangan. Ati paluwas iya minnē' buwat a'a bastigan ya kinōgan magdagan ma paglomba'an.",
        6: "Pasobang mata llaw min bihing langit dakayu' bo' pas'ddop ni bihingna dakayu', maka halam aniya' minsan ai mbal taluwa' pasu'na.",
        7: "Ajukup asal sara' bay pinat'nna' e' si Yawe, ya na sara' makahayang palnyawahan manusiya'. Kapangandolan ai-ai pangahatul e' si Yawe, ya na hatulan pangā'an pangita'u e' a'a bilahi pinandu'an.",
        8: "Abontol saga pamandu' si Yawe, ya na pandu' makalasig deyom pikilan. Asawa panoho'an si Yawe, ya na panoho'an makaranta' panghati manusiya'.",
        9: "Asussi pagmatāw ma si Yawe, sabab taptap anatas ni kasaumulan. Atuman kamemon pangahandak si Yawe, a'adil lullun, halam aniya' salla'na minsan ai.",
        10: "Labi ahalga' pangahandakna min bulawan, minsan bulawan porol landu' aheka. Labi amamis min gula' buwani minsan gula' masi am'ttak min sāng buwani.",
        11: "Binanda'an sosoho'annu e' ai-ai pangahandaknu, maka aheya tungbas ma sasuku angisbat.",
        12: "Sai bahā' makakilā kasā'an baranna? Bang manjari ampunin aku ya dusa halam tasayuku.",
        13: "Hawirin aku bo' mbal magtu'ud angandusa. Da'a aku pasagarin pinagbaya'an e' dusa pagtu'ud-tu'uran. Jari mbal aku katōngan dusa, ati abontol itikadku pagka halam bay makahinang dusa aheya.",
        14: "Ya PANGHŪ', bang pa'in ka kasulutan ma bissalaku maka ma hona'-hona'ku, sabab ka'a ya batu-lakit pamalutanku, ka'a ya Manglalappas ma aku.",
    },
    22: {
        1: "O Tuhanku, angay aku siya-siyanu? Angay ka palawak na pa'in min aku? Angay halam takalenu pangandahingku?",
        2: "O Tuhanku, anganjunjung aku ni ka'a kahaba' llaw, saguwā' mbal aku sambungannu. Angamu'-ngamu' aku ni ka'a kahaba' sangom, sagō' halam aniya' halianku.",
        3: "Malaingkan ilu ka aningkō' ma deyom kamahaldika'an. Ka'a ya Tunggal Mahasussi, ya pinudji e' bangsa Isra'il.",
        4: "Bay angiman ma ka'a saga kamatto'ahan kami, bay sigām pasangdol ni ka'a ati liyusannu min kasigpitan.",
        5: "Bay sigām parahing ni ka'a, ati lappasannu, bay sigām angandol ma ka'a, ati halam karapatan.",
        6: "Saguwā' aku itu sali' kalog tana', sali' ngga'i ka manusiya'. Niudju' aku he' pagkahiku, nihalipulu e' kampungku.",
        7: "Pinakaiya' aku he' sasuku ang'nda'. Nihina' aku, pinagelong-elongan, pinagtunggīng.",
        8: "Ya lling sigām ma aku, “A'a itu angandol ma si Yawe, na, patabangta iya ma PANGHŪ' -Yawe. Kalu iya pinuwas min kasigpitan, pagka aheya lasa PANGHŪ' ma iya.”",
        9: "Malaingkan, Tuhanku, ka'a ya bay amaluwas aku min kulunan ina'ku. Tabowa aku angandol ma ka'a min kariki'-diki'ku gi', min waktuku onde' duru'an lagi'.",
        10: "Ka'a ya kaholatanku min llaw kapaganak ma aku, ka'a ya Tuhanku sangay min kapangiram ma aku.",
        11: "Da'a kono' ka pala'an min aku, sabab itiya' aku marai' taluwa' kasusahan. Luwal ka'a ya makatabang.",
        12: "Sikapūn-pūnan ni aku ba'anan palbantahanku, sapantun sapi' mandangan min lahat Basan.",
        13: "Pinabanga' bowa' sigām tudju ni aku, sapantun halimaw marai' na an'kkob, an'kkat.",
        14: "Angalongkoy anggauta'ku, magsalisi' lullun to'olangku. Angalunuk atayku, ibarat lansuk atunaw e' pasu'.",
        15: "Katoho'an k'llongku, buwat katoho' buli' lapohan. Angakkot d'lla'ku ni isi emponku, tahinangnu aku anginam bagunbun nalka'.",
        16: "Aniya' sapantun ero' ma sakalibutku, pinagtipunan aku he' a'a jahulaka'. Nilagbas e' sigām tape'-tanganku.",
        17: "Ta'nda'an di-na bokogku kamemon, pinatong aku e' saga a'a ab'nsihan aku, kinōgan sigām ma kala'at pangluwahanku.",
        18: "Pinagbahagi'an s'mmekku he' sigām, pinagko'ot-ko'ot badju'ku bang sai makarapu.",
        19: "Ya PANGHŪ', da'a pa'in ka palawak min aku. Ka'a ya ga'osanku, bang pa'in ka pasa'ut anabang.",
        20: "Tampanin aku bo' mbal taōk e' kalis. Ahalga' ma aku nyawaku, angkan amu'ku pinuwas min kosog saga ero' itu.",
        21: "Liyusun aku min bowa' halimaw, papuwasun aku min tanduk sapi' talun.",
        22: "Ati pasaplagku ōnnu ni dauranakanku, pudjiku ka ma palhimpunan saga jama'anu.",
        23: "Ka'am ya magmatāw ma si Yawe, pudjihunbi! Ka'am saga panubu' si Yakub, pagmahaltabatinbi! Ka'am bangsa Isra'il kamemon, hulmatunbi!",
        24: "Sabab halam pabiyalna pagdahing saga a'a asukkal, halam bay pasagaranna ma deyom kasigpitan. Halam bay taikutanna sasuku angamu'-ngamu', gom pa'in tabangna.",
        25: "O Tuhan, ka'a ya pagpudjihanku ma palhimpunan aheya, suhulku isab najalku ma matahan saga a'a magmatāwan ka'a.",
        26: "Amangan saga miskin ma sinosōng sampay sigām asso. Sasuku kam angangut ma si Yawe ananglit du ma iya. Mura-murahan, bang pa'in kam allum saumul-umul.",
        27: "Kinannal si Yawe he' a'a kamemon ma mpat pidju alam itu, ati papinda sigām magta'at ni iya. Magpudji sabarang bangsa ma alopanna,",
        28: "sabab PANGHŪ' -Yawe ya tag-parintahan ma dunya. Iya ya makapagagi ma kabangsa-bangsahan.",
        29: "Sasuku taga-karaya ma dunya itu, sigām balkanan, pasujud du ma alopan Tuhan. Sasuku amole' lahat kamatayan magpatireyo' ma iya, sampay saga a'a ya mbal makapakalluman di-sigām, pasujud du.",
        30: "Ni'isbat Tuhan e' panubu' magsuring-magsaingsing, pinandu'an sigām pasal si Yawe ma sinosōng.",
        31: "Ati sigām ya pas'lle' amatanyag ni saga a'a halam gi' palahil pasal kabontolan ya tahinang e' Tuhan ma sabab a'a suku'na.",
    },
    23: {
        1: "Si Yawe ya angipat aku, sapantun a'a angipat bili-bilina, angkan halam aniya' kulang ma aku.",
        2: "Kahinangan aku he'na pahalian ma parang-parang alunuk, niambit aku he'na ni atag bohe' kasannangan.",
        3: "Pinahayang nyawaku, minaliman aku he'na ma lān abontol, ma sabab Ōnna kabantugan.",
        4: "Minsan palabayanku kal'ddoman lambung kamatay, mbal aku atāw pinuhinga' sabab ka'a ya gapi'ku, O Tuhan. Ilu tungkudnu maka soha'nu amuwanan aku kasalamatan baran.",
        5: "Sakapannu aku jamuhan ma alopan palbantahanku. Ni'ns'llanan he'nu kōkku, tanda' sin lasanu ma aku. Palasay sawanku pagka ap'nno' he' pahala'.",
        6: "Tantu aku pinasuku'an kahāpan, tantu tinogolan lasanu ma aku sat'ggolku allum. Ati luma' PANGHŪ' ya pat'nna'anku saumul-umul.",
    },
    24: {
        1: "Suku' PANGHŪ' dunya itu sampay kapanyapanna. Suku'na alam itu sampay kabangsa-bangsahanna.",
        2: "Pinat'nna' e'na gintana'an ma t'ngnga' s'llang, pinahogot he'na ma t'ngnga' kas'llogan.",
        3: "Sai bahā' makatukad ni būd PANGHŪ'? Sai bahā' makat'ngge ma deyom luma' pangarapan ni iya?",
        4: "Luwal a'a ya asussi tanganna min dusa, ya apote' deyom pangatayanna. Luwal isab a'a ya mbal anumba ni ta'u-ta'u, maka mbal magsapa pagputingan.",
        5: "Makasambut pahala' min PANGHŪ' bang a'a buwattē' kajarihanna. Tinungbasan iya kabontolan itikad e' Tuhan Manglalappas.",
        6: "Buwattē' isab kahālan saga a'a ya angangut Tuhan, ya atuyu' paharap ni ka'a, O Tuhan si Yakub.",
        7: "Bang pa'in paukab saga tambol! Bang pa'in paukab saga lawang awal-jaman, bo' supaya makasōd Sultan Sanglit-sahaya!",
        8: "Sai sa Sultan Sanglit-sahaya itu? Si Yawe ko' itu, ya landu' akosog, landu' aesog. PANGHŪ' ko' itu, ya makaga'os ma pagbono'.",
        9: "Bang pa'in paukab saga tambol! Bang pa'in paukab saga lawang awal-jaman, bo' supaya makasōd Sultan Sanglit-sahaya!",
        10: "Sai sa Sultan Sanglit-sahaya itu? Si Yawe ko' itu, ya Sangat Kawasa. Ya na Sultan Sanglit-sahaya!",
    },
    27: {
        1: "Si Yawe ya amuwanan aku kasawahan maka kalappasan, angkan halam aniya' katāwanku. PANGHŪ' -Yawe ya sapantun kuta' pangahampan kallumku, angkan halam aniya' kagawahanku.",
        2: "Bang aku sinekot e' a'a jahallis, ya bilahi angamula baranku, bang aku nirugpak e' ba'anan bantaku, tantu sigām makarugtul, makahantak.",
        3: "Minsan aku nilikusan he' tumpukan ba'anan sundalu, mbal kin'bba-k'bba atayku. Minsan aku t'kkahan pagbono', ahantap na pa'in pangatayanku.",
        4: "Luwal itu ya pangamu'ku ni PANGHŪ' -Yawe, luwal itu ya pagmatayanku, bang pa'in aku paokom ma luma' Tuhan sat'ggolku allum ma babaw dunya itu. Landu' aku bilahi ang'nda' ma kahāp palantarana, maka angaruhan iya ma luma'na pangarapan.",
        5: "Angkan buwattē', sabab tinampanan aku he'na ma waktu katumbuk kasusahan. Pinakuta'an aku e'na ma pussuk batu-lakit, tinapukan aku sakuli-kuli ma luma' pagtata'atan ni iya.",
        6: "Minnē' aku anganda'ug min palbantahanku, pinalanga aku min saga banta ma katilibutku. Tukbalanku pagkulban ni PANGHŪ' -Yawe ma langgal ya pangarapan iya, hinabuku angolang kabowa kakōganku. Angalang isab aku, pagpudjiku PANGHŪ'.",
        7: "O PANGHŪ', kalehun lagi' panganjunjungku, ka'ase'in aku, sambungin aku.",
        8: "Ah'llingan aku di-ku, “Panuyu'in si Yawe.” Jari patuyu' aku ma ka'a, O PANGHŪ'.",
        9: "Da'a kono' ka pataikut min aku sabab sosoho'annu aku. Da'a pa'in akagit ataynu, da'a aku taikutin, sabab ka'a ya pananabang ma aku. Da'a aku palehomun, da'a aku bbahin, sabab ka'a ya Tuhanku Manglalappas.",
        10: "Abila aku siniya-siya he' ina'-mma'ku, tantu aku tinaima' e' PANGHŪ'.",
        11: "Ya, PANGHŪ', pandu'in aku lānnu, ya amowa ni kahāpan. Malimin aku ma lān abontol, sabab aheka a'a angangut angala'at aku.",
        12: "Da'a aku pasagarin pinagbaya'an e' saga kuntaraku, sabab aniya' a'a anuna'an aku kaputingan. Ya kab'ngngis sigām mbal kaliyuhan.",
        13: "Saguwā' minsan buwattē', aniya' kaholatanku tuman. Tantu aku makabāk kahāpan min si Yawe, hinabuku lagi' ma dunya dakayu' itu.",
        14: "Angkan yukku, “Pangasahin si Yawe. Pahogotunbi imanbi, pataptapunbi pangatayanbi, pangaholatinbi PANGHŪ' -Yawe.”",
    },
    32: {
        1: "Aheya kahāpan ma sasuku niampun kala'atanna, sasuku pinapasan paldusahanna.",
        2: "Aheya kahāpan ma sasuku abontol ma bistahan PANGHŪ', sasuku halam aniya' kaputingan ma pangatayanna.",
        3: "Sat'ggol limbunganku dusaku, anitis na pa'in bokogku ma sabab pangandahingku kahaba' llaw.",
        4: "Kabuhatan aku llaw-sangom, sali' kahantang tangannu ya makabuhat. Angalongkoy kuwat-anggauta'ku, buwat a'a apanggang ma musim pang'llaw.",
        5: "Malaingkan bay tapamattanku dusaku ni ka'a, halam bay limbunganku kala'atanku. Yukku, “Gom aku magpasab'nnal ni PANGHŪ',” magtūy ta'ampunnu kasā'anku kamemon.",
        6: "Angkan sasuku magtata'at subay angamu'-ngamu' ni ka'a ma waktu kahanggawna. Bang pasōng kasusahanna sapantun latap alalom, mbal iya alimun he' susa.",
        7: "O Tuhan, ka'a ya patapukanku, ka'a ya angahampanan aku min kajahatan. Alibut aku e' saga a'a magkalangan aku ma sabab kalappasnu ma aku.",
        8: "Yuk Tuhan ni aku, “Pandu'anta ka lān ya wajib palabayannu. Hūganta ka gara' ati peyananku ka.",
        9: "Da'a ka pasali' ni kajarihan kura', ya halam aniya' akkalna. Mbal tasoho' hayop inān, mbal tapasekot ni ka'a, luwal bang sangonannu kakkang maka engkot.”",
        10: "Aheya karukka'an saga a'a ya ala'at kajarihanna, saguwā' sasuku angandol ma si Yawe, ap'nno' iya e' kasi-lasa PANGHŪ'.",
        11: 'Kalasiginbi si Yawe. Pakoyag kam sasuku ahāp kajarihanbi. Magkalang kam sasuku abontol itikadbi.',
    },
    37: {
        1: "Da'a kahanggawinbi saga a'a jahulaka', da'a isab pangihirinbi saga a'a maghinang kala'atan!",
        2: "Sapantun sigām parang-parang al'kkas alanos, sapantun dahun ak'llos magdai'-dai'.",
        3: "Angandol sadja kam ma PANGHŪ' -Yawe, hinangunbi kahāpan. Pat'nna' kam ma lahatbi porol, pat'nna' kam ma deyom kasannangan.",
        4: "Paglasiginbi PANGHŪ' ati kabuwanan kam ai-ai ya makasulut pangatayanbi.",
        5: "Pama'andolunbi kahālanbi ni PANGHŪ', pasangdolinbi iya, ati tahinang e'na ya amu'bi.",
        6: "Pinabukis he'na ka'adilanbi, sapantun sawa ya pabukis dai'-llaw, pinasaplag kabontol palkala'bi, sapantun sinag llaw bang augtu.",
        7: "Pat'mmun kam ma alopan si Yawe, lagarinbi iya. Da'a kam asusa bang auntung saga a'a kasehe'an, bang tahinang kagara'an sigām ajahallis.",
        8: "Da'a kam angastol! Da'a kam angamahit! Da'a papasu'un ataybi, tantu ala'at kat'kkahanna.",
        9: "Sabab pinahalam saga a'a ala'at kajarihanna, saguwā' sasuku angasa ma PANGHŪ' pinusaka'an lahat itu.",
        10: "Mbal at'ggol, pahalam saga a'a ala'at itu. Minsan painay e'bi amiha, mbal tabāk.",
        11: "Sagō' saga a'a areyo' pangatayanna pinasuku'an lahat itu, ati halam aniya' makasasaw kasannangan sigām.",
        12: "Binantuhan a'a ahāp atayna he' a'a jahulaka'. Ang'ttop le'e saga a'a inān, tanda' sin kab'nsi sigām ma a'a ahāp.",
        13: "Malaingkan pinagtittowahan he' PANGHŪ' saga a'a jahulaka', sabab kata'uwanna aniya' llaw pangangganta' ma sigām.",
        14: "Angahublut kalis saga a'a jahulaka', anakap ba'ugan pana' sigām, bo' tapana' e' sigām saga a'a kamiskinan maka kasigpitan. Ya maksud sigām amapatay saga a'a abontol atayna.",
        15: "Saguwā' papelleng kalis inān angandugsu' jantung sigām, pinagpōng-pōng isab saga ba'ugan pana' sigām.",
        16: "Minsan akulang ai-ai ya palsuku'an ma saga a'a abontol, labi ahalga' ko' inān min alta' manglabi-labihan ya palsuku'an saga a'a ala'at.",
        17: "Sabab pahalam ya ga'osan saga a'a jahulaka', sagō' angandapit PANGHŪ' -Yawe ma saga a'a abontol palangayna.",
        18: "Niayuput e' si Yawe kallum sasuku mbal katōngan dusa ati anatas pusaka' sigām sampay ni kasaumulan.",
        19: "Mbal sigām aiya' bang t'kkahan kasigpitan. Minsan ma waktu gotom, maka'ssohan kinakan sigām.",
        20: "Malaingkan saga a'a jahulaka' magka'at lullun. Palanyap saga palbantahan PANGHŪ', ibarat humbu. Ibarat sigām kalingkat sumping ya patomo' ma deya, dai'-dai' du palanos bo' halam na.",
        21: "Angutang saga a'a ala'at sagō' mbal amayad. Saguwā' saga a'a ahāp magmura sadja,",
        22: "sabab sai-sai kabuwanan pahala' he' PANGHŪ' pinusaka'an lahat itu. Saguwā' sai-sai sinapdahan e' PANGHŪ', tantu magmula.",
        23: "Bang kasulutan PANGHŪ' ma kaul-pi'il a'a, pinatotog e'na tekangna.",
        24: "Minsan iya makarugtul, mbal tabowa pahantak, sabab PANGHŪ' -Yawe ya amalutan tanganna.",
        25: "Min kaonde'-onde'ku sampay ni kato'aku itu, halam aniya' a'a abontol bay ta'nda'ku pinasagaran he' Tuhan. Halam isab ta'nda'ku anak a'a inān tabowa angamu' kinakan.",
        26: "Magmura sadja sigām amuwan maka amautang, angkan pinaniya'an pahala' saga anak sigām e'.",
        27: "Angkan yukku, pataikut kam min kala'atan bo' patukid ma kahāpan, ati taptap kam pat'nna' ma lahatbi porol.",
        28: "Angkan buwattē', sabab kasulutan PANGHŪ' ma a'a angahinang kabontolan. Mbal palehomna saga a'a ya atukid angisbat iya. Nihampanan e'na saga a'a suku'na sampay ni kasaumulan, saguwā' bin'kkat e'na napas saga a'a maghinang kala'atan.",
        29: "Pamusaka' ma a'a ahāp ya lahat sigām porol, ati maglahat sigām maina'an salama-lama tahun.",
        30: "Bang a'a asussi pangatayanna, amissala iya pangita'u, abontol maka asaltun himumūnganna.",
        31: "Ina'an ma deyom atayna sara'-manara' min Tuhanna, angkan mbal parasdas tape'na.",
        32: "Tinipu saga a'a ahāp palangayna he' a'a ala'at, sabab angamohot amapatay,",
        33: "saguwā' mbal pinasagaran he' si Yawe saga a'ana gina'os he' a'a jahulaka'. Bang sigām pinaharap ni huwis, mbal tugutanna sigām taluwa' hukuman.",
        34: "Pangaholatinbi PANGHŪ', bogboginbi panoho'anna ati pinalanga kam bo' pinusaka'an lahatbi porol. Song isab ta'nda'bi saga a'a jahulaka' pinahalam.",
        35: "Aniya' bay ta'nda'ku a'a landu' ajahat maka abigsi', ahāp sadja kahālanna, sapantun kayu alabung dahunna, ya patomo' ma tana' bay asal patomo'anna.",
        36: "Sagō' da'a ka pilang'llaw paglabayku minnē', na halam na. Minsan painay he'ku amiha iya, halam to'ongan tabākku.",
        37: "Kira-kirahunbi a'a halam dusahan, pangli'unbi a'a abontol palangayna, sabab ahāp kasōngan ma saga a'a mbal bilahi maglugat.",
        38: "Saguwā' tantu pinaka'at kamemon saga baldusa, halam aniya' kasōngan a'a maghinang kala'atan.",
        39: "Lappasan sasuku asussi pangatayanna, sabab min PANGHŪ', ya sapantun kuta' pasindungan a'ana bang t'kkahan bala'.",
        40: "Tinabang sigām e' si Yawe, pinuwas e'na min kasigpitan. Niliyus sigām e'na min ga'osan saga a'a jahallis, nilappas isab sigām sabab Tuhan iya pangandolan.",
    },
    40: {
        1: "Angagad na pa'in aku ma si Yawe minsan mbal anambung saru'un-du'un, jari palingi' iya ni aku bo' akale ma panabbutku.",
        2: "Bay aku binuhat e'na min kal'bbohan, pinaluwas aku min lowang kapisakan. Pinat'ngge aku ma batu, pinahogot pat'nggehanku.",
        3: "Aniya' kalangan baha'u pamakalangna ma aku, kalangan pamudji Tuhantam. Aheka a'a magmatāw pag'nda'na ma pakaradja'an itu, ati angandol sigām ma si Yawe.",
        4: "Aheya kahāpan ma sasuku apagon pangandolna ma PANGHŪ', ya mbal ameya' ma saga a'a magabbu-abbu, atawa ma a'a ya magta'at ma tuhan-tuhan puting!",
        5: "O Yawe, Tuhanku, aheka hinangnu makainu-inu. Mbal taitung saga kahāpan ya mohotnu ma kami. Bang aku bay pasulay anuli-nuli kamemon, mbal takole' sinuli-suli pagga kumarukan hekana.",
        6: "Ngga'i ka tutukbalan maka tapung ya pagmatayannu, ngga'i ka susumbali'an tinunu', ngga'i ka tataubatan dusa ya kagunahannu. Saguwā' tin'bbok e'nu taingaku, hatina pinakale aku.",
        7: "Magtūy aku ah'lling, yukku, “Itiya' aku, sakap aku, buwat tasulat ma Kitab ma pasalanku.",
        8: "O Tuhanku, ahutu aku angahinang kabaya'annu. Itiya' ma aku sara'nu, ma deyom pangatayanku.”",
        9: "Bay pasaplagku kabontol pangahandak si Yawe ma palhimpunan aheya. Kata'uwannu asal, PANGHŪ', halam bay tambolku bowa'ku.",
        10: "Mbal tahananku ma atay kabontolnu, ah'lling na pa'in aku pasal kapangandolannu maka kalappasnu. Halam bay limbunganku kasi-lasanu maka kab'nnalnu, gom pa'in pagnasihatku ma palhimpunan aheya.",
        11: "Ya PANGHŪ', da'a pa'in ka'llogin ase'nu ma aku. Hampanin aku sakahaba' waktu maka lasanu kakkal, maka kab'nnalannu.",
        12: "Sabab itiya' aku t'kkahan susa-manusa ya mbal taitung itiya' aku kapilahan e' ba'anan dusaku. Palabi hekana min heka lamba bu'unku, angkan aku mbal na maka'nda' pahāp, angahimāt pangatayanku pagka halam aniya' pangasa.",
        13: "O PANGHŪ', bang pa'in aku lappasnu, O Yawe, bang pa'in ka pasa'ut anulung!",
        14: "Bang pa'in pinahina' maka pinaligoto' e'nu saga a'a kamemon ya anganiyat amapatay aku. Bang pa'in hawirannu saga a'a bilahi angamula aku, bang pa'in sigām tahinang pagtunggīngan.",
        15: "Saga a'a isab ya bay anittowahan aku, bang pa'in sigām kapam'ngngangan ma sabab iya' sigām.",
        16: "Saguwā' saga a'a ya angaholat ma ka'a, Tuhan, bang pa'in sigām kinōgan maka ka'amuhan ma ka'a. Sasuku kasulutan ma kakosog panglappasnu, subay anabbut sararan-daran: “Akawasa si Yawe! Akawasa si Yawe!”",
        17: "Maka aku itu, minsan kamiskinan maka kasigpitan, kinannal isab aku he' PANGHŪ'. O Tuhan, ka'a ya Mananabang maka Manglalappas ma aku, Pasa'ut ka kono'.",
    },
    46: {
        1: "Tuhan ya patapukanta maka pangā'anta kosog, asakap iya anabang bang aniya' kasukkalan.",
        2: "Angkan kita mbal tināw minsan ajogjog dunya, minsan al'bbos kabūd-būran tudju ni timbang.",
        3: "Aho', minsan magabal tahik, minsan amukal, minsan isab ahenggol saga būd he' kosog haus.",
        4: "Sagō' aniya' sapa' anasahan amowa kakōgan ni da'ira Tuhan, ni lugal sussi ya haddarat Tuhan Mahatinggi.",
        5: "Ina'an Tuhan ma deyom da'irana, angkan mbal pajudjal. Pagk'llat llaw, tinabang he' Tuhan.",
        6: "Maglengogan kabangsa-bangsahan. Pah'bba' kapagsultanan. Angabtang sadja Tuhan, magtūy atunaw dunya.",
        7: "Pataptap PANGHŪ' Sangat Kawasa ma kita, kuta' pasindunganta ya Tuhan pangkatta si Yakub.",
        8: "Dai' kam, nda'unbi kahinangan si Yawe, ya hinang makak'bbal atay bay tahinangna ma dunya.",
        9: "Pinahondong he'na ba'anan pagbono' ma kaluha'an dunya. Pinagpōng he'na ba'ugan pana', pinagp'ppot saga budjak, Pinagtunu' tampan sundalu ma deyom api.",
        10: "“Pahali kam, pahati kam in aku Tuhan. Patut aku pinalanga he' kabangsa-bangsahan. Patut aku pinalanga to'ongan ma dunya.”",
        11: "Pataptap PANGHŪ' Sangat Kawasa ma kita, Kuta' pasindunganta ya Tuhan pangkatta si Yakub.",
    },
    51: {
        1: "O Tuhan, ka'ase'in aku ma sabab lasanu kakkal. Patiase'un ka, angkan amu'ku pinapasan paldusahanku.",
        2: "Kose'in aku min kasā'anku, sussihun aku min dusaku.",
        3: "Sabab kata'uwanku na kala'atanku, mbal takalipatku, pamikilanku na pa'in sakahaba' waktu.",
        4: "Ya dusaku itu dusa ni ka'a sadja, ngga'i ka dusa ni manusiya'. B'nnal, bay aku amakay dusa ni ka'a, angkan taluwa' bang aku katōngannu dusa. Abontol ka. Taluwa' isab bang aku pat'nna'annu hukuman.",
        5: "Tantu aku dusahan waktu lagi' kapaganak ma aku, dusahan aku min waktu kapangiraman ina'ku ma aku.",
        6: "Tantu isab, ya kabaya'annu subay aniya' kab'nnalan sampay min deyom atay. Ya pamandu'nu pasal pangita'u itiya' pasobsob ni itikadku.",
        7: "Sussihun aku maka sayul hissup, ati alanu' aku. Pandihun aku, ati apote' aku min pote' gapas.",
        8: "Pakalehun aku lling pagkoyagan, paglasigan. Pakōrun kuwat-anggauta'ku, ya bay pinananaman kakagit ataynu.",
        9: "O Tuhan, bang pa'in ka pakeleng min paldusahanku, maka papasin kasā'anku kamemon.",
        10: "Paniya'in aku atay sussi, pabaha'uhun itikadku bo' mbal magpinda-pinda.",
        11: "Da'a kono' aku paluwasun min haddaratnu. Da'a la'anin min aku Rū-nu Sussi.",
        12: "Pabīngun ni aku kalasigan ya bay ma aku tagna' kapangalappasnu ma aku. Buwanin aku kajarihan ahutu bo' tahinangku kabaya'annu.",
        13: "Jari pandu'anku saga a'a ya angalanggal sara'nu, pandu'anku sigām pasal kaul-pi'il ya makasulut ataynu. Ati aniya' saga a'a dusahan pabalik ni ka'a.",
        14: "O Tuhan, ka'a Tuhan Manglalappas, puwasin aku min dusa amapatay a'a ati angalang aku pasal kabontol pangahandaknu.",
        15: "O Tuhan, PANGHŪ', pakalangun aku, bo' ka sanglitanku labay min suwalaku,",
        16: "Bang pagkulban ya kabaya'annu, bay du ka bowahanku. Mbal ka kasulutan ma susumbali'an pinagtunu'.",
        17: "Ya huhulmatan pagmatayan Tuhan, ya na atay ata'u magsusun. O Tuhan, mbal sowaynu atay pagsususun maka atay areyo'-deyo'.",
        18: "Bangunun da'ira Siyun ma sabab lasanu hilas. Pahāpun tambak batu ya bay pangād ma da'ira Awrusalam.",
        19: "Minnē' aniya' tutukbalan abontol pangahulmat ka'a. Aniya' susumbali'an pinagtunu' ma katibu'ukanna, maka aniya' sapi' l'lla pinagkulban ma panukbalan ya ma luma'nu.",
    },
    61: {
        1: "Ya Tuhan, kalehun panangisku, taima'un pangamu'-ngamu'ku.",
        2: "Angalingan aku ni ka'a min lahat ya katapusan alawak pagka halam aniya' holatanku. Malimin aku ni batu alanga ya mbal ta'abutku.",
        3: "Sabab ka'a ya bay patapukanku, ibarat kuta' mbal tasōd e' saga bantaku.",
        4: "Landu' aku bilahi pat'nna' ma Luma' Pangarapan ni ka'a bo' magluma' mailu sat'ggolku allum, ati pasindung aku ma deyo' kepetnu sapantun anak manuk.",
        5: "Ya Tuhanku, tasambutnu bay janji'ku ma ka'a, ati kabuwanan aku kahāpan ya pamusaka'nu ma sasuku magmatāw ma ōnnu.",
        6: "Bang pa'in pataha'nu umul sultan, bang pa'in pahogotnu pagsultanna sampay ma panubu'na.",
        7: "Mura-murahan, bang pa'in iya magsultan ma matahannu salama-lama tahun. Hampanin iya pahāp ma sabab lasanu maka janji'nu ya mbal magkapinda.",
        8: "Jari aku itu angalang na pa'in pamudjiku ōnnu, ati suhulku ai-ai bay panganajalku ma ka'a, tukbalanku ni ka'a kahaba' llaw.",
    },
    63: {
        1: "O Tuhan, ka'a ya Tuhanku, landu' aku angentom ma ka'a. Bang aku alawak min haddaratnu, ya sapantunna lahat paslangan halam aniya' bohe'na. Patay bohe' palnyawahanku, apanggang baranku ma sabab katuyu'ku ma ka'a.",
        2: "Bay ka ta'nda'ku ma deyom Luma' Pangarapan ka'a, bay ta'nda'ku kawasanu maka sahayanu.",
        3: "Ahalga' lasanu, labi ahalga' min kallumku, angkan ka sanglitanku luwas min k'llongku.",
        4: "Pudjiku ka sat'ggolku allum. Anangga aku hinabuku anabbut ōnnu.",
        5: "Asalamat nyawaku, sapantun a'a asso he' kinakan ahāp lanabna, angkan aku angalang pamudji ka'a luwas min k'llongku.",
        6: "Taentomku ka'a hinabuku palege ma pabahakanku, ati ka'a ya paghona'-hona'ku kahaba'-kahaba' sangom.",
        7: "Ka'a ya anabangan aku, angkan aku tabowa angalang hinabuku pasindung ma pikpiknu, sali' manuk-manuk.",
        8: "Pabalut pangatayanku ma ka'a, pinatotog aku he' tangannu sakap kowan.",
        9: "Bang pa'in palurus ni kalaloman ahirat saga a'a ya magisun amapatay aku.",
        10: "Bang pa'in sigām tinugutan binono' patay kalis bo' pinagkakan he' saga ero' paslangan.",
        11: "Pagubus, magkalasigan sultan ma Tuhan. Sinanglitan isab Tuhan e' sasuku anganjanji' ma ōnna. Malaingkan pinakittup bowa' saga a'a magputing.",
    },
    66: {
        1: "Ka'am kamemon ma dunya, olanginbi Tuhan ma sabab kakoyagbi!",
        2: "Magkalang kam pamaheyabi ōnna kawasahan! Pudjihunbi iya bo' pasōng kabantuganna!",
        3: "Amissala kam ni Tuhan, yukbi, “Ya Tuhan, akawasa du pa'in kahinangannu, mbal tasipat! Magpatiata saga palbantahannu ni ka'a sabab kawasanu mbal tasagga'.",
        4: "Pasujud ni ka'a sabarang bangsa ma deyom dunya. Angalang sigām pananglit ka'a, pinudji ōnnu ma kalangan sigām.”",
        5: "Pi'itu kam ang'nda' ma bay tahinang he' Tuhan. Makatāw-tāw saga kahinangan ya tahinang e'na pangahāp kitam panubu' si Mbo' Adam.",
        6: "Ya tahik bay tahinang he'na katoho'an, bo' magtinape' saga a'a parambila'. Angkan kitam subay magkōg-koyagan Tuhan,",
        7: "ya magparinta sampay saumul-umul ma sabab kawasana. Pineyanan he'na palbangsa-bangsahan, supaya halam aniya' min sigām angatu ma iya.",
        8: "Ka'am saga bangsa, pudjihunbi Tuhantam, patanogunbi suwalabi pananglit ma iya.",
        9: "Niliyusan kitam min kamatay, pineyanan kitam bo' mbal parasdas tape'tam.",
        10: 'Bay kami sulayannu, Tuhan, bay kami tatabnu, sapantun pilak tinatab ma panarulan.',
        11: 'Bay kami kalabusunu, sapantun daing ma pokot, bay kami patanggungnu tanggungan abuhat.',
        12: "Makahantak pa'in kami, bay tugutannu saga a'a angura' palabay min kōk kami. Bay kami palabay isab min deyom api maka min bohe', arak amatay, manda' kami paluwasnu bo' pinasampay ni lahat magdayas-dayas ma kinakan.",
        13: "Pi'ilu aku ni luma'nu angungsuran pagkulban tinunu', maka hinangku bay pagnajalku ni ka'a.",
        14: "Hinangku in janji' bay kak'bbatan bowa'ku, hinabuku bay kasigpitan.",
        15: "Tukbalanku ni ka'a bili-bili al'mmok maka kambing l'lla tinunu' ma katibu'ukanna. Ungsuranku ni ka'a susumbali'an sapi' maka kambing.",
        16: "Sasuku kam magmatāw ma Tuhan, pi'itu kam akale ati pangahakaku ma ka'am bay kahinanganna ma aku.",
        17: "Bay aku parahing ni iya, bay iya sanglitanku maka pangallam bowa'ku.",
        18: "Abila aku bay anganapsuhan la'at ma deyom atayku, mbal aku kinale he' Panghū'ku.",
        19: "Saguwā' tantu aku kinale he' Tuhan, ta'asip e'na pangamu'-ngamu'ku.",
        20: "Pudjitam Tuhan, ya halam bay amabiyal pagduwa'aku, ya halam bay pahali alasahan aku.",
    },
    84: {
        1: "Ya PANGHŪ', Tuhan Sangat Kawasa! Kalingkat du pa'in pat'nna'annu ilu!",
        2: "Sali' aku apunung e' baya'ku pi'ilu ni halaman luma' PANGHŪ'. Magkalang aku ni Tuhan kakkal ma sabab kakōranku, luwas min palnyawahanku maka min ginhawa-baranku.",
        3: "Minsan saga manuk-manuk paupit makabāk pat'ppakan ma atag paghinangan kulban ni ka'a. Sampay saga manuk-manuk baliyu makahinang pugaranna mailu pangint'llohanna. Ya PANGHŪ', Tuhan Sangat Kawasa! Ka'a ya Sultanku, ka'a ya Tuhanku.",
        4: "Aheya kahāpan sasuku pat'nna' ma deyom luma'nu, sabab makasanglit sigām ma ka'a ma halam aniya' hogga'anna.",
        5: "Aheya kahāpan ma sasuku makasambut kosog min ka'a, ya angangut patukad ni Awrusalam bo' anambahayang.",
        6: "Pasalta' sigām palabay min l'bbak Baka, tahinang lugal pagbohe'an. Ta'abut pa'in waktu pangulan, ap'nno' l'bbak inān e' kalowang-lowangan taga-bohe'.",
        7: "Paganap na pa'in kosog sigām, bo' paganap, sampay sigām paharap pakaniya-kaniya ni Tuhan ma da'ira Siyun.",
        8: "Ya PANGHŪ', Tuhan Sangat Kawasa, Tuhan si Yakub, bang pa'in sambutnu pangamu'-ngamu'ku itu.",
        9: "O Tuhan, nda'un gi' sultan ya makatampanan kami. Nda'un pamaihu'anna, in iya a'a tapene'nu.",
        10: "Aku itu, pād-pād dangibu llaw maingga-maingga lahat, gom lagi' dang'llaw ma deyom halaman luma'nu. Pād-pād aku pat'nna' ma kaluma'an saga a'a jahulaka', gom lagi' ma luma'nu, minsan hal an'ngge ma atag bowa' lawang.",
        11: "Sabab Tuhan Yawe sali' ād maka tampan ma saga a'ana. Amuwan iya hulmat maka mahaltabat. Sasuku ahongpot tebongna mbal kinaiskutan he' Tuhan ai-ai ahāp.",
        12: "O Tuhan Sangat Kawasa aheya kahāpan ma sasuku angandol ma ka'a.",
    },
    91: {
        1: "Sasuku pat'nna' ma sindungan Tuhan Mahatinggi pahali-hali ma limbuhan Sangat Kawasa.",
        2: "Buwattitu pah'llingku, “Si Yawe ya pahogotanku. Sapantun iya kuta' patapukanku, pangandolanku iya.”",
        3: "Tantu iya amuwasan ka'a min jallat ya pinat'nna'an ka'a, maka min saki makapatay.",
        4: "Tinambunan ka e'na ma sabakanna, ibarat manuk. Pasindung ka ma deyo' pikpikna. Tuhan ya sapantun ād makahampanan ka'a sabab mbal to'ongan apinda kajarihanna.",
        5: "Mbal kagawahannu bangsa magl'l'ngngan ma kalendoman, atawa budjak ya nihiyak waktu llaw.",
        6: 'Mbal isāb katāwannu saki maglunsulan ma sangom, atawa bonglay ya makalaglag bang ugtu llaw.',
        7: "Abugtang pa'in dangibu a'a ma atagnu kowan, sangpū' ngibu pa'in ma atagnu gibang, mbal ka talapay.",
        8: "Ta'nda' hal he' matanu bang ai panungbas Tuhan ma saga a'a jahulaka'.",
        9: 'Bang Tuhan Mahatinggi ya pataptapannu, hatina si Yawe ya patapukanku isab,',
        10: "mbal ka t'kkahan bala', mbal sinekot luma'nu he' saki bonglay,",
        11: "sabab aniya' saga mala'ikat sinō' he' Tuhan angahampanan ka'a pi'ingga-pi'ingga pal'ngnganannu.",
        12: "Tinayak ka e' sigām bo' mbal makasantuk tape'nu ni batu.",
        13: "Gi'ikannu halimaw maka sowa d'ppong, kagindasan e'nu halimaw maka buwaya.",
        14: "Angallam si Yawe, yukna, “Alasa a'a itu ma aku, angkan liyusku iya min kajahatan, Angaku iya ma ōnku, angkan iya hampananku.",
        15: 'Pagsabbutna ma aku, sambunganku magtūy. Pataptap aku ma iya hinabuna ma deyom sukkal. Tabangku iya ma deyom kasigpitan, maka buwananku iya ōn abantug.',
        16: "Ka'amuhan iya pagga pataha'ku umulna. Pata'uku iya bang buwattingga pangalappasku.”",
    },
    93: {
        1: "Si Yawe ya magsultan ma kamemon, pagmahaldika'an sultan mahatinggi ya pamakayna. Ga'osan sultan iya pakambot hawakanna. Magsin'mmek iya kamahaltabatan. Ahogot papagan dunya itu, mbal tajudjal.",
        2: "Ya Tuhan, ahogot kapagsultannu, sangay min awal tagna'. Ka'asalnu dahū gi' min kapamapanjari dunya.",
        3: "O Yawe, ang'llub saga s'llang, angabal tahik, alandos pangabalna, angalagublub kalumbagan tahik.",
        4: "Landu' aheya pangulattub goyak, aheya isab pang'llub goyak pasampoyak. Saguwā' labi lagi' aheya ga'osan si Yawe, ya katapusan alanga.",
        5: "Atantu pangahatulnu, mbal magpinda-pinda. Alingkat luma'nu e' kasussina. Alingkat ni kasaumulan, O PANGHŪ'.",
    },
    95: {
        1: "Dai' na kam, magkalang kitam ni si Yawe kabowa kakōgan, Patanogtam suwalatam ni iya, ya pinagsambatan Batu-Lakit panglappasan.",
        2: 'Sūng kitam anukbal pagsukulan ni iya, paheyatam iya labay min kalangan maka tarasul.',
        3: "Sababna si Yawe ya Tuhan makaga'os, sultan abantug, alanga min katuhan-tuhanan kamemon.",
        4: "Tinayak he'na po'onan dunya itu. Dapuna asal saga kapussukan būd.",
        5: "Suku'na asal saga katahikan, sabab iya ya bay amapanjari. Iya na isab bay angompol gintana'an.",
        6: "Dai' na kam, pasujud kitam amudji iya. Angōk-tu'ut kitam ma alopan PANGHŪ' Magpapanjari,",
        7: "kalna' in iya pagtuhanantam, maka kitam saga a'ana, sapantun bili-bili ma pangipatanna. Na, ma llaw itu, bang takalebi bissala Tuhan, yukna,",
        8: "“Da'a patuwasunbi kōkbi buwat bay ka'mbo'-mbo'anbi ma Meriba, buwat bay ma Massa isab, ma lahat paslangan.",
        9: "Bay aku sinulayan maka tinukas he' ka'mbo'anbi, sinulayan aku he' sigām, minsan du bay kalabayan he' sigām kahinanganku.",
        10: "Mpatpū' tahun bay kap'ddi' atayku ma pangkatan ina'an-i. Saga a'a itu,” yukku, “mbal makatotog ameya' ma aku. Halam tata'u e' sigām kaul-pi'il ya kabaya'anku.",
        11: "Bay akagit atayku ati pagsapahanku sigām,” yukku, “Saga a'a itu mbal to'ongan pasōd ni lahat pahalian bay tagamaku.”",
    },
    100: {
        1: "Ka'am kamemon ma dunya itu, patanogun suwalabi amudji si Yawe, kabowa kakōganbi.",
        2: "Ta'atunbi PANGHŪ' -Yawe luwas min kakoyaganbi, pabaihu' kam ma iya maka kalanganbi makalasig.",
        3: "Ta'uhunbi si Yawe, in iya Tuhan. Si Yawe ya bay amapanjari kitam, ati suku'na kitam. A'ana kitam, sapantun bili-bili ma pangipatanna.",
        4: "Palabay kam min saga lawangna salta' kam magsarang-sukul. Pasōd kam ni halaman luma'na hinabubi magpudji. Pagsukulinbi iya, pudjihunbi ōnna!",
        5: "Sabab ahāp kasuddahan PANGHŪ', maka taptap lasana kasi. Kapangandolan iya salama-lama tahun.",
    },
    103: {
        1: "Pudjiku si Yawe min deyom pangatayanku. Pudjiku ōnna sussi min palnyawahanku maka min kuwat-anggauta'ku.",
        2: "Aho', pudjiku PANGHŪ' min deyom pangatayanku, mbal takalipat kamemon kahāpan ya bay pamuwanna.",
        3: "Sabab iya ya angampun kamemon paldusahanbi. Iya ya amauli' kamemon sakibi.",
        4: "Iya isāb angal'kkat kallumbi min lahat kamatayan. Iya isab amalipatan ka'am lasa maka ase'.",
        5: "Iya ya amuwanan ka'am ginisan kahāpan ya makahāp palasahanbi, angkan tabawi' bay kosog kabata'bi. Sapantun kam belle' ya mbal ata'u binale'.",
        6: "Abontol PANGHŪ' -Yawe ma kahinanganna kamemon, pinabontol e'na hukuman ma sasuku pininjala' e' sara'.",
        7: "Bay pata'una si Musa pasal kaniyatanna. Bay pa'nda'na hinangna ni bangsa Isra'il.",
        8: "Patiase'un maka patilasahun asal PANGHŪ' -Yawe, mbal akagit atayna magdai'-dai', gom pa'in palabi lasana tuman.",
        9: "Mbal iya paddas amabukag, mbal anatas ka'astolna sampay ni kasaumulan.",
        10: "Mbal kita pinat'nna'an kabinasahan ya makatōpan dusata. Mbal kita tinungbasan e'na ma buwat hinangta ala'at.",
        11: "Sabab-kalna', landu' aheya lasana ma sasuku magmatāwan iya. Mbal tabista kaheya lasana itu, buwat diyata' langit mbal tabista langkawna min babaw dunya.",
        12: "Pinalawak e'na paldusahantam, buwat lawak sobangan maka s'ddopan.",
        13: "Aheya ase' ma sasuku magmatāw ma iya, buwat ka'ase' matto'a ma panganakna.",
        14: "Sabab kinata'uwan asal e'na ya bay pangompolan kitam manusiya'. Taentomna in kitam bay nihinang min bagunbun tana'.",
        15: "Ya niōnan manusiya' itu mbal anatas, sapantun parang-parang dai'-dai' patubu'. Sapantun sumping huma dai'-dai' manisna.",
        16: "Pagtumbuk pa'in baliyu, magtūy halam na. Mbal taentom bay kamahē'na.",
        17: "Malaingkan ya kasi-lasa PANGHŪ' ni sasuku magmatāw ma iya anatas min awal tagna' sampay ni kasaumulan. Pasampay kahandakna abontol ni anak-mpu saga a'a kamemon,",
        18: "sasuku amogbogan kapagsulutan sigām maka Tuhan, maka atukid ameya' ma pandu'na.",
        19: "Pinatuman e' si Yawe pagparintana ma sulga' ati magtuhan iya ma papanjarihanna kamemon.",
        20: "Pudjihunbi PANGHŪ' -Yawe, ka'am saga mala'ikatna patikawasahun ya angahinang kahandak Tuhan, ya ameya' ma panoho'anna.",
        21: "Pudjihunbi PANGHŪ', ka'am kalaksa'-laksa'an ya sosoho'anna ma deyom sulga', maka ka'am ya maghinang kabaya'anna.",
        22: "Pudjihunbi PANGHŪ', ka'am papanjarihanna, pudjihunbi iya maingga-maingga ma pagparintahanna. Pudjiku isab PANGHŪ' sampay min buli'-atayku.",
    },
    119: {
        1: "Aheya kahāpan ma sasuku mbal katōngan dusa, ya atukid ameya' ma bay panara' si Yawe.",
        2: "Aheya kahāpan ma saga a'a ya magkahagad ma pandu'na, ya magmatayan Tuhan sadja.",
        3: "Mbal sigām angahinang kala'atan, gom pa'in sigām an'ppu kajarihanna.",
        4: "O PANGHŪ', bay ka amat'nna'an kami hatulan ya wajib bineya' to'ongan.",
        5: "Mura-murahan bang pa'in aku makatuyu' ameya' ma ai-ai pangahandaknu.",
        6: "Mbal aku tahinang pagiya'an, bang tahona'-hona'ku panoho'annu kamemon.",
        7: "Pudjiku ka magatay pote', hinabuku angadji' panara'nu ya landu' abontol.",
        8: "Ameya' du aku ma pangahandaknu, da'a pa'in aku siya-siyahun.",
        9: "Buwattingga he' subul anussi kajarihanna? Luwal bang panunuranna palmannu.",
        10: "Ka'a ya pagmatayanku, Tuhan, da'a aku tugutin pasā' min panoho'annu.",
        11: "Tatau'ku palmannu ma deyom pangatayanku bo' supaya mbal amakay dusa ni ka'a.",
        12: "O Yawe, bang pa'in aheya barakat ma ka'a, pandu'in lagi' aku pasal kahandaknu.",
        13: "Usulku na pa'in saga panara' bay pangallamnu.",
        14: "Kinōgan aku ameya' ma pandu'nu, buwat a'a magkōgan pangalta' aheya.",
        15: "Panoho'annu ya pagtali'anku kahaba' waktu, pamikilanku na pa'in kajarihannu.",
        16: "Ka'amuhan aku ma pangahandaknu, mbal palehomku palmannu.",
        17: "Pagmurahun sosoho'annu itu, ati allum aku, maka amogbog pahāp ma palmannu.",
        18: "Pasawahun lagi' pikilanku bo' ahāp e'ku ang'nda' ma sara'nu makainu-inu.",
        105: "O PANGHŪ', palmannu itu sapantun palita'an ma pal'ngngananku, suwariyan ma labayanku.",
        106: "Bay aku makasapa maka bay patumanku, in aku ameya' to'ongan ma panara'nu, ya adil lullun.",
        129: "Makainu-inu pamandu'nu, angkan bogboganku to'ongan.",
        130: "Palmannu ya pangā'an sawa pamaranta' pikilan manusiya', minsan a'a akulang pangadji'na makahati du isab.",
    },
    121: {
        1: "Pahangad aku ang'nda' tudju ni kabūran. Minningga aku makabāk tabang?",
        2: "Tinabang aku he' si Yawe, ya bay amapanjari langit maka dunya.",
        3: "Mbal pasagaranna tape'nu parasdas ma lān. Mbal tatuli ya anganjagahan ka'a.",
        4: "Mbal talilap ya anunggu'an bangsa Isra'il, tantu iya mbal tatuli.",
        5: "Si Yawe ya anganjagahan ka'a, pasindungannu si Yawe pataptap ma bihingnu kowan.",
        6: "Mbal ka kinapiyalu bang llaw, mbal ka taluwa' bulan bang sangom.",
        7: "PANGHŪ' -Yawe ya angahampanan ka'a bo' mbal ta'abut la'at. PANGHŪ' ya ameyanan kallum-nyawanu.",
        8: "PANGHŪ' ya anganjagahan ka'a ma katulaknu maka ma kapole'nu, min llaw itu sampay ni kasaumulan.",
    },
    139: {
        1: "O Yawe, bay aku tatabnu, kata'uwannu aku maka kapaga'aku.",
        2: "Ata'u ka ma katingkō'ku maka ma kapundukku, kasakupannu pamikilku minsan min kalawakan.",
        3: "Ata'u ka ma kalunsulku maka kalegeku, tahimangkannu kajarihanku kamemon.",
        4: "O Yawe, bang aku sōng amaluwas bissala, asal kata'uwannu kamemonna ma halam gi' tak'bbat.",
        5: "Nilikusan aku e'nu min dahuwan maka min bukutan, kapat'nna'an aku tangannu.",
        6: "Landu' makahaylan pangita'u buwattilu, mbal takannalku. Landu' alanga, mbal ta'abutku.",
        7: "Ya PANGHŪ', pi'ingga aku bo' makalahi min Rū-nu? Pi'ingga palahianku bo' kaillaganku haddaratnu?",
        8: "Bang aku pa'angkat ni langit diyata', mailu ka asal. Bang aku pabahak ma lahat kamatay, mailu isab ka.",
        9: "Bang aku paleyang ni pasobangan llaw ati maglahat aku ma dambila' s'llang,",
        10: "ina'an ka isab angamaliman aku, komkomannu aku maka tangannu sakap kowan.",
        11: "Bang aku angupama, yukku, “Tantu aku katambunan e' kalendoman, papinda isab llaw ni sangom ma katilibutku,”",
        12: "halam aniya' dapat, sabab halam aniya' lendom ma ka'a. Minsan sangom anahaya sali' llaw, sabab sali' du lendom maka sawa bang ma ka'a.",
        13: "Ka'a PANGHŪ', bay amapanjari ginhawa-baranku, tabatuk e'nu pagdayawku hinabuku lagi' ma deyom kandang ina'ku.",
        14: "Aheya pudjiku ni ka'a, sabab ainu-inu aku, sinōd aku tāw, ma sabab ginhawa-baran ya hinangannu aku. Tata'uku asal, makainu-inu kahinangan kamemon.",
        15: "Halam katapukan min ka'a pagdayaw baranku waktu lagi' kapagbatuk ma aku ma kuta' kuddarat. Waktu isab kapanganyam ma aku ma kalaloman gumi,",
        16: "ta'nda'nu aku ma halam gi' ajukup kapaga'aku. Tasulat asal saga llaw ya pangangganta'nu ma aku, tasulat ma deyom kitabnu, tasulat dahū lagi' min llaw kalahilku.",
        17: "Ya Tuhan, ahalga' ma aku kahona'-hona'nu, kumarukan hekana, mbal tasipat.",
        18: "Bang aku angitung kahona'-hona'annu, paheka lagi' min solagan gusung ma kaluha'an dunya.",
        19: "Ya Tuhan, bang pa'in papataynu saga a'a jahallis! Ka'am saga bula'ug, ala'an kam min aku!",
        20: "Tuhan, pinamūng-mūngan ka pangkal e' saga a'a inān, pinahina' ōnnu e' palbantahannu.",
        21: "O Yawe, aheya kab'nsiku ma sasuku ab'nsihan ka'a. Sasuku angatu ma kapagbaya'nu, asammal ma pang'nda'ku.",
        22: "Mbal kasandalan kab'nsiku ma saga a'a inān, itungku sigām sali' bantaku.",
        23: "O Tuhan, lilingun aku bo' tata'unu deyom pangatayanku, tatabun aku bo' tata'unu bang ai kahanggawanku.",
        24: "Tandingun aku, ya aniya' makala'at ma iman-nyawaku, ati malimin aku ma lān ya kakkal min awal ni ahil.",
    },
    143: {
        1: "O Yawe, kalehun lagi' pangamu'-ngamu'ku. Kalehun panganjunjungku, ka'ase'in aku. Pasa'ut ka kono' anabangan aku, sabab kapangandolan ka maka abontol.",
        2: "Aku itu sosoho'annu, da'a aku sara'un, sabab halam aniya' manusiya' abontol ma pang'nda'nu.",
        3: "Tinurul aku he' bantaku, ginindasan aku e'na, pinodjak aku. Pinat'ddas aku he'na ma deyom kalendoman, sapantun a'a at'ggol na kamatayna.",
        4: "Halam aniya' kaholatanku, alamma palnyawahanku, angaloyot pangatayanku kabowa sukkalna.",
        5: "Amagtak ni atay saga patahunan palabay, angahona'-hona' aku pasal kahinangannu, amikil-mikil pasal hinang tangannu kamemon.",
        6: "Jari anangga aku tudju ni ka'a, mbal kasandalan pagmatay ma ka'a, sapantun a'a patay bohe' ma lahat apanggang.",
        7: "O PANGHŪ', pasa'ut lagi' ka anambung, sabab angalongkoy iman-nyawaku. Bang ka pataikut min aku, tantu aku pasali' ni saga a'a ya amole' lahat.",
        8: "Bang pa'in aniya' habal pagdai'-llaw angalapalan aku pasal lasanu kakkal, sabab angandol du aku ma ka'a. Pandu'in aku lān ya wajib pal'ngngananku, sabab ka'a ya pangaholatan palnyawahanku.",
        9: "O Yawe, liyusun aku kono' min saga bantaku, sabab ka'a ya patapukanku.",
        10: "Pandu'in aku bo' tabeya'ku ai-ai pangahandaknu aku, sabab ka'a ya Tuhanku. Bang pa'in aku minaliman he' Rū-nu ahāp, supaya aku makal'ngngan ma lān aratag.",
        11: "Ya PANGHŪ', pakallumun aku ma sabab kabantug ōnnu. Puwasin aku min kasukkalan ma sabab kabontol palangaynu.",
        12: "Laglagun lagi' palbantahanku ma sabab lasanu kakkal. Pahalamun saga a'a kamemon ya anguntarahan aku, sabab atanu du aku.",
    },
    148: {
        1: "Pudji ni si Yawe! Pudjihunbi iya min deyom sulga', pudjihunbi min kalangahan langit.",
        2: "Ka'am saga mala'ikatna, pudjihunbi iya, ka'am sosoho'anna patikawasahun, pudjihunbi.",
        3: "Ka'am mata llaw maka bulan, pudjihunbi si Yawe, ka'am saga bitu'un magsasahaya, pudjihunbi iya.",
        4: "Saga ma kalangkawan katapusan, amudji kam ma iya, Saga bohe' ma diyata'an langit, amudji kam.",
        5: "Patut pinabantug ōn si Yawe e' ai-ai pinapanjari sabab angallam sadja iya ati paniya' magtūy.",
        6: "Pinat'nna'an sigām lugal min kahandakna, pinat'nna'an sigām ganta'an ya anatas ni kasaumulan.",
        7: "Pudjihunbi si Yawe ma kaluha'an dunya, ka'am saga sattuwa maka sasuku ma kategob-tegoban,",
        8: "l'tte' maka tigtigan aes, alu' aes maka gabun, saga badju ya angahinang kabaya'anna,",
        9: 'kamemon kabūd-būran maka kabīd-bīran, saga kabbun maka saga kayu sidro,',
        10: "kaginisan sattuwa talun maka kamemon sapi' ni'ipat, manuk-manuk palē maka manuk-manuk pikpikan",
        11: "saga kasultanan ma dunya maka palbangsa-bangsahan, saga a'a balbangsa maka saga magbabaya',",
        12: "saga onde' baha'u subul-budjang, kamanahutan maka kato'ahan.",
        13: "Papudjihun kamemon pinapanjari itu, soho'un amabantug ōn si Yawe sabab luwal ōnna ya patut binantug. Minsan maingga ma dunya, minsan isab ma sulga' halam aniya' makaliyu min kamahaldika'an si Yawe.",
        14: "Aniya' a'a patikosogun pinaniya' e'na panabang saga a'ana, a'a pinagmahaltabatan e' kamemon suku'na, e' saga panubu' si Isra'il, ya bangsa kalasahanna.",
    },
}
